// NVM-03: fault memory - a simplified AUTOSAR DEM (decision of the user 2026-09-21: status byte, debouncing, enable
// conditions, operation cycles, confirmation, aging, snapshots and extended data; no warning lamp, no OBD).
//
// Everything that describes a DTC is configuration (dem::Config, generated by tools/rtegen from diag.yaml); this
// class is the behaviour only, family and board neutral, with host tests (libs/bsw/dem/test).
//
// Behaviour (ISO 14229-1 (2026), Annex D; only clause numbers cited):
// - Events are sampled once per mainFunction() cycle (Config::cycleMs) from ISource, or reported by the BSW through
//   report() (taken over in the next cycle; a failed report between two cycles is not lost).
// - Debouncing turns samples into a matured result and keeps the fault detection counter -128..127 (D.6): counter
//   based with jumps (the first failed sample after passed ones jumps over zero, so the DTC is prefailed at once) or
//   time based. FAILED/PASSED of a status source mature at once.
// - Status byte (D.2.2): a matured failure sets bits 0, 1, 2, 5 and clears 4 and 6; a matured pass clears 0, 4 and
//   6. The confirmation (bit 3) follows after confirmationThreshold operation cycles with a failure (D.2.1); the DTC
//   is stored then (entry with snapshot and extended data identifiers). Start of its operation cycle: bit 1 cleared,
//   bit 6 set, debouncing restarts. End of the cycle: a DTC tested without failure loses bit 2 (pending).
// - Aging (D.7): a confirmed DTC counts operation cycles of its aging cycle that ended tested and without failure;
//   at agingThreshold it loses bit 3 and its entry.
// - Enable conditions: while one of a DTC's conditions does not hold, its samples are discarded (debouncing stands).
// - ControlDTCSetting off (setDtcSetting(false)): no status bit changes at all except by clear() (D.2.1). COM-43: a
//   report() of a BSW monitor is discarded while it is off (the level stays the one reported before), so what a
//   monitor reported during the preprogramming step of a flash sequence never becomes a DTC after it (like the
//   disabled DTC setting of AUTOSAR, where the reports are not taken over either).
// - clear(): status 0x50, counters and debouncing to zero, entry deleted.
// - testFailed is not a fail-safe reaction (D.2.1): the fault memory only records; safety reactions stay with the
//   safe supervisor (SYS-19), which may report the event here after it has reacted.
//
// Concurrency: mainFunction() runs in one context (the DEM context of the integration); every public call takes
// Lock (on the target ::async::LockType, which also protects the RTE). Data identifiers of a new entry are read
// without the lock (IDidReader may take the RTE lock itself) into the scratch buffer, then committed under it.

#pragma once

#include "dem/DemTypes.h"
#include "dem/IFaultMemory.h"

#include <cstddef>
#include <cstdint>
#include <cstring>

namespace dem
{

template<class Lock>
class Manager final : public IFaultMemory
{
public:
    /**
     * \param states   one per DTC (config.dtcCount)
     * \param entries  config.maxEntries
     * \param data     config.maxEntries * config.entryDataBytes: stored data of the entries
     * \param scratch  config.entryDataBytes: data identifiers of a new entry before it is committed
     */
    Manager(Config const& config, DtcState* const states, Entry* const entries, uint8_t* const data, uint8_t* const scratch)
    : _config(config)
    , _states(states)
    , _entries(entries)
    , _data(data)
    , _scratch(scratch)
    , _reader(nullptr)
    , _stamp(0U)
    , _overflows(0U)
    , _displaced(0U)
    , _conditions(config.initialConditions)
    , _running(0U)
    , _dtcSetting(true)
    , _loaded(false)
    , _eventsDirty(false)
    , _entriesDirty(false)
    {
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            _states[i].latchValid  = false; // the reported level of a BSW event survives a clear, not a restart
            _states[i].latchFailed = false;
            _states[i].latchLast   = Result::NONE;
        }
        clearAllLocked();
        _eventsDirty  = false;
        _entriesDirty = false;
    }

    Manager(Manager const&)            = delete;
    Manager& operator=(Manager const&) = delete;

    Config const& config() const { return _config; }

    /** Reader of the data identifiers of snapshots and extended data; nullptr: registry().didReader. */
    void setDidReader(IDidReader* const reader) { _reader = reader; }

    // ------------------------------------------------------------------------------------------ persistence

    /**
     * Loads the persistent state from the two NvM images (before start()). An image with another header (the NvM
     * default is all zeros, or another layout) leaves the memory cleared. Returns true if both were valid.
     */
    bool load(uint8_t const* const events, size_t const eventsBytes, uint8_t const* const entries, size_t const entriesBytes)
    {
        Lock const lock;
        clearAllLocked();
        _eventsDirty  = false;
        _entriesDirty = false;
        bool const eventsOk = (eventsBytes == eventsBlockBytes(_config.dtcCount)) && (events[0] == NVM_MAGIC)
                              && (events[1] == NVM_FORMAT_EVENTS) && (get16(&events[2]) == _config.dtcCount);
        // entries only with their events: an entry belongs to a confirmed DTC of the events block
        bool const entriesOk = eventsOk
                               && (entriesBytes == entriesBlockBytes(_config.maxEntries, _config.entryDataBytes))
                               && (entries[0] == NVM_MAGIC) && (entries[1] == NVM_FORMAT_ENTRIES)
                               && (entries[2] == _config.maxEntries);
        if (eventsOk)
        {
            for (uint16_t i = 0U; i < _config.dtcCount; ++i)
            {
                uint8_t const* const p              = &events[NVM_HEADER_BYTES + (NVM_EVENT_RECORD * i)];
                _states[i].status                   = static_cast<uint8_t>(p[0] & status::AVAILABILITY_MASK);
                _states[i].occurrence               = p[1];
                _states[i].aging                    = p[2];
                _states[i].failedCycles             = p[3];
                _states[i].cyclesSinceFirstFailed   = p[4];
            }
        }
        if (entriesOk)
        {
            for (uint8_t e = 0U; e < _config.maxEntries; ++e)
            {
                uint8_t const* const p = &entries[NVM_HEADER_BYTES + (e * (NVM_ENTRY_HEADER + _config.entryDataBytes))];
                uint16_t const dtc     = get16(&p[0]);
                // an entry of an unknown DTC or twice the same DTC is dropped (the layout id of the block protects the
                // rest; this keeps a bit error from pointing outside the tables)
                if ((dtc == 0U) || (dtc > _config.dtcCount) || (entryOfLocked(static_cast<uint16_t>(dtc - 1U)) >= 0))
                {
                    continue;
                }
                _entries[e].dtc   = dtc;
                _entries[e].stamp = get32(&p[2]);
                (void)std::memcpy(entryData(e), &p[NVM_ENTRY_HEADER], _config.entryDataBytes);
                _stamp = (_entries[e].stamp >= _stamp) ? (_entries[e].stamp + 1U) : _stamp;
            }
        }
        if (eventsOk && entriesOk)
        {
            // a confirmed DTC without an entry (entries block lost) keeps its bit; an entry without the bit is dropped
            for (uint8_t e = 0U; e < _config.maxEntries; ++e)
            {
                if ((_entries[e].dtc != 0U)
                    && ((_states[_entries[e].dtc - 1U].status & status::CONFIRMED_DTC) == 0U))
                {
                    _entries[e] = Entry{0U, 0U};
                }
            }
        }
        _loaded = eventsOk && entriesOk;
        return _loaded;
    }

    /** true once if the state changed since the last call: serializeEvents() should go to the NvM. */
    bool takeEventsDirty()
    {
        Lock const lock;
        bool const dirty = _eventsDirty;
        _eventsDirty     = false;
        return dirty;
    }

    bool takeEntriesDirty()
    {
        Lock const lock;
        bool const dirty = _entriesDirty;
        _entriesDirty    = false;
        return dirty;
    }

    /** Persistent part of every DTC into \p out (eventsBlockBytes(dtcCount) bytes). */
    void serializeEvents(uint8_t* const out, size_t const bytes) const
    {
        if (bytes != eventsBlockBytes(_config.dtcCount))
        {
            return;
        }
        Lock const lock;
        out[0] = NVM_MAGIC;
        out[1] = NVM_FORMAT_EVENTS;
        put16(&out[2], _config.dtcCount);
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            uint8_t* const p = &out[NVM_HEADER_BYTES + (NVM_EVENT_RECORD * i)];
            p[0]             = _states[i].status;
            p[1]             = _states[i].occurrence;
            p[2]             = _states[i].aging;
            p[3]             = _states[i].failedCycles;
            p[4]             = _states[i].cyclesSinceFirstFailed;
        }
    }

    /** The entries into \p out (entriesBlockBytes(maxEntries, entryDataBytes) bytes). */
    void serializeEntries(uint8_t* const out, size_t const bytes) const
    {
        if (bytes != entriesBlockBytes(_config.maxEntries, _config.entryDataBytes))
        {
            return;
        }
        Lock const lock;
        out[0] = NVM_MAGIC;
        out[1] = NVM_FORMAT_ENTRIES;
        out[2] = _config.maxEntries;
        out[3] = 0U;
        for (uint8_t e = 0U; e < _config.maxEntries; ++e)
        {
            uint8_t* const p = &out[NVM_HEADER_BYTES + (e * (NVM_ENTRY_HEADER + _config.entryDataBytes))];
            put16(&p[0], _entries[e].dtc);
            put32(&p[2], _entries[e].stamp);
            (void)std::memcpy(&p[NVM_ENTRY_HEADER], entryData(e), _config.entryDataBytes);
        }
    }

    // ------------------------------------------------------------------------------------------ cycle

    /** Starts the autostart operation cycles (after load(), when the ECU starts). */
    void start()
    {
        Lock const lock;
        for (uint8_t c = 0U; c < _config.cycleCount; ++c)
        {
            if ((_config.autostartCycles & bit8(c)) != 0U)
            {
                startCycleLocked(c);
            }
        }
    }

    /** Ends every running operation cycle (run-down of the ECU, before the NvM writes). */
    void stop()
    {
        Lock const lock;
        for (uint8_t c = 0U; c < _config.cycleCount; ++c)
        {
            if ((_running & bit8(c)) != 0U)
            {
                endCycleLocked(c);
            }
        }
    }

    /** Starts (\p running true) or ends operation cycle \p cycle (console, application driven cycles). */
    void setCycle(uint8_t const cycle, bool const running)
    {
        if (cycle >= _config.cycleCount)
        {
            return;
        }
        Lock const lock;
        bool const now = (_running & bit8(cycle)) != 0U;
        if (running && now)
        {
            endCycleLocked(cycle); // a restart ends the running cycle first
        }
        if (running)
        {
            startCycleLocked(cycle);
        }
        else if (now)
        {
            endCycleLocked(cycle);
        }
    }

    /** One cycle (every Config::cycleMs): conditions, application cycles, one sample per event, storage. */
    void mainFunction(ISource& source)
    {
        uint32_t conditions = 0U;
        for (uint8_t i = 0U; i < _config.conditionCount; ++i)
        {
            conditions |= source.condition(i) ? bit32(i) : 0U;
        }
        {
            Lock const lock;
            _conditions = conditions;
        }
        for (uint8_t c = 0U; c < _config.cycleCount; ++c)
        {
            uint8_t const state = source.cycleState(c);
            if (state != ISource::CYCLE_AUTOMATIC)
            {
                Lock const lock;
                bool const now = (_running & bit8(c)) != 0U;
                if ((state != 0U) && !now)
                {
                    startCycleLocked(c);
                }
                else if ((state == 0U) && now)
                {
                    endCycleLocked(c);
                }
            }
        }
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            DtcConfig const& dtc = _config.dtcs[i];
            Result result        = Result::NONE;
            if (dtc.reportedBy == nullptr)
            {
                result = source.sample(i);
            }
            bool store = false;
            {
                Lock const lock;
                if (dtc.reportedBy != nullptr)
                {
                    result = takeLatchLocked(_states[i]);
                }
                store = processLocked(i, result);
            }
            if (store)
            {
                storeEntry(i);
            }
        }
    }

    // ------------------------------------------------------------------------------------------ IFaultMemory

    uint16_t dtcCount() const override { return _config.dtcCount; }

    DtcConfig const& dtcConfig(uint16_t const dtc) const override { return _config.dtcs[dtc]; }

    bool dtcInfo(uint16_t const dtc, DtcInfo& info) const override
    {
        if (dtc >= _config.dtcCount)
        {
            return false;
        }
        Lock const lock;
        DtcState const& s           = _states[dtc];
        info.number                 = _config.dtcs[dtc].number;
        info.status                 = static_cast<uint8_t>(s.status & status::AVAILABILITY_MASK);
        info.severity               = _config.dtcs[dtc].severity;
        info.fdc                    = s.fdc;
        info.occurrence             = s.occurrence;
        info.aging                  = s.aging;
        info.failedCycles           = s.failedCycles;
        info.cyclesSinceFirstFailed = s.cyclesSinceFirstFailed;
        info.stored                 = entryOfLocked(dtc) >= 0;
        return true;
    }

    int32_t findDtc(uint32_t const number) const override
    {
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            if (_config.dtcs[i].number == number)
            {
                return static_cast<int32_t>(i);
            }
        }
        return -1;
    }

    uint16_t countByStatusMask(uint8_t const mask) const override
    {
        Lock const lock;
        uint16_t count = 0U;
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            count = static_cast<uint16_t>(
                count + (((_states[i].status & static_cast<uint8_t>(mask & status::AVAILABILITY_MASK)) != 0U) ? 1U : 0U));
        }
        return count;
    }

    MemoryInfo memoryInfo() const override
    {
        Lock const lock;
        MemoryInfo info{};
        for (uint8_t e = 0U; e < _config.maxEntries; ++e)
        {
            info.entriesUsed = static_cast<uint8_t>(info.entriesUsed + ((_entries[e].dtc != 0U) ? 1U : 0U));
        }
        info.maxEntries    = _config.maxEntries;
        info.overflows     = _overflows;
        info.displaced     = _displaced;
        info.conditions    = _conditions;
        info.cyclesRunning = _running;
        info.dtcSetting    = _dtcSetting;
        info.loaded        = _loaded;
        return info;
    }

    int32_t readSnapshot(uint16_t const dtc, uint8_t const record, uint8_t* const out, size_t const max) const override
    {
        if (dtc >= _config.dtcCount)
        {
            return -1;
        }
        DtcConfig const& dtcCfg = _config.dtcs[dtc];
        uint32_t offset         = 0U;
        for (uint8_t r = 0U; r < dtcCfg.snapshotCount; ++r)
        {
            uint32_t bytes = 0U;
            for (uint8_t i = 0U; i < dtcCfg.snapshots[r].count; ++i)
            {
                bytes += dtcCfg.snapshots[r].items[i].bytes;
            }
            if (dtcCfg.snapshots[r].number == record)
            {
                return copyStored(dtc, offset, bytes, out, max);
            }
            offset += bytes;
        }
        return -1;
    }

    int32_t readExtended(uint16_t const dtc, uint8_t const record, uint8_t* const out, size_t const max) const override
    {
        if (dtc >= _config.dtcCount)
        {
            return -1;
        }
        DtcConfig const& dtcCfg = _config.dtcs[dtc];
        uint32_t offset         = 0U; // stored identifiers of the extended data follow the snapshots
        for (uint8_t r = 0U; r < dtcCfg.snapshotCount; ++r)
        {
            for (uint8_t i = 0U; i < dtcCfg.snapshots[r].count; ++i)
            {
                offset += dtcCfg.snapshots[r].items[i].bytes;
            }
        }
        Lock const lock;
        int32_t const entry = entryOfLocked(dtc);
        for (uint8_t r = 0U; r < dtcCfg.extendedCount; ++r)
        {
            ExtendedRecord const& rec = dtcCfg.extended[r];
            if (rec.number != record)
            {
                for (uint8_t i = 0U; i < rec.count; ++i)
                {
                    offset += (rec.items[i].content == Counter::DID) ? rec.items[i].bytes : 0U;
                }
                continue;
            }
            size_t written = 0U;
            for (uint8_t i = 0U; i < rec.count; ++i)
            {
                ExtendedItem const& item = rec.items[i];
                if ((written + item.bytes) > max)
                {
                    break;
                }
                if (item.content == Counter::DID)
                {
                    if (entry >= 0)
                    {
                        (void)std::memcpy(&out[written], &entryData(static_cast<uint8_t>(entry))[offset], item.bytes);
                    }
                    else
                    {
                        (void)std::memset(&out[written], 0xFF, item.bytes);
                    }
                    offset += item.bytes;
                }
                else
                {
                    out[written] = counterValue(_states[dtc], item.content);
                }
                written += item.bytes;
            }
            return static_cast<int32_t>(written);
        }
        return -1;
    }

    bool clear(uint32_t const group) override
    {
        Lock const lock;
        if (group == GROUP_ALL_DTCS)
        {
            clearAllLocked();
            return true;
        }
        int32_t const dtc = findDtc(group);
        if (dtc < 0)
        {
            return false;
        }
        clearLocked(static_cast<uint16_t>(dtc));
        return true;
    }

    void setDtcSetting(bool const enabled) override
    {
        Lock const lock;
        _dtcSetting = enabled;
    }

    int32_t findReportedEvent(char const* const name) const override
    {
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            char const* const reported = _config.dtcs[i].reportedBy;
            if ((reported != nullptr) && (name != nullptr) && (std::strcmp(reported, name) == 0))
            {
                return static_cast<int32_t>(i);
            }
        }
        return -1;
    }

    void report(uint16_t const dtc, Result const result) override
    {
        if ((dtc >= _config.dtcCount) || (_config.dtcs[dtc].reportedBy == nullptr) || (result == Result::NONE))
        {
            return;
        }
        Lock const lock;
        if (!_dtcSetting)
        {
            return; // COM-43: ControlDTCSetting off, the report is not taken over
        }
        DtcState& s = _states[dtc];
        s.latchValid = true;
        s.latchLast  = result;
        if ((result == Result::FAILED) || (result == Result::PREFAILED))
        {
            s.latchFailed = true;
        }
    }

private:
    static constexpr uint8_t bit8(uint8_t const n) { return static_cast<uint8_t>(1U << n); }

    /** Status byte with bits set / cleared; every operand stays 8 bit unsigned (no promoted int in a chain). */
    static constexpr uint8_t setBits8(uint8_t const value, uint8_t const bits)
    {
        return static_cast<uint8_t>(value | bits);
    }

    static constexpr uint8_t clearBits8(uint8_t const value, uint8_t const bits)
    {
        return static_cast<uint8_t>(value & static_cast<uint8_t>(~bits));
    }

    /** Status bits a matured failure sets and clears (D.2.2), composed unsigned. */
    static constexpr uint8_t FAILED_SETS = static_cast<uint8_t>(
        static_cast<uint32_t>(status::TEST_FAILED) | status::TEST_FAILED_THIS_OPERATION_CYCLE | status::PENDING_DTC
        | status::TEST_FAILED_SINCE_LAST_CLEAR);
    static constexpr uint8_t FAILED_CLEARS = static_cast<uint8_t>(
        static_cast<uint32_t>(status::TEST_NOT_COMPLETED_SINCE_LAST_CLEAR)
        | status::TEST_NOT_COMPLETED_THIS_OPERATION_CYCLE);
    /** Status bits a matured pass clears. */
    static constexpr uint8_t PASSED_CLEARS = static_cast<uint8_t>(
        static_cast<uint32_t>(status::TEST_FAILED) | status::TEST_NOT_COMPLETED_SINCE_LAST_CLEAR
        | status::TEST_NOT_COMPLETED_THIS_OPERATION_CYCLE);

    static constexpr uint32_t bit32(uint8_t const n) { return 1UL << n; }

    static void put16(uint8_t* const p, uint16_t const v)
    {
        p[0] = static_cast<uint8_t>(v & 0xFFU);
        p[1] = static_cast<uint8_t>(v >> 8U);
    }

    static void put32(uint8_t* const p, uint32_t const v)
    {
        for (uint8_t i = 0U; i < 4U; ++i)
        {
            p[i] = static_cast<uint8_t>((v >> (8U * i)) & 0xFFU);
        }
    }

    static uint16_t get16(uint8_t const* const p)
    {
        return static_cast<uint16_t>(static_cast<uint16_t>(p[0]) | static_cast<uint16_t>(p[1] << 8U));
    }

    static uint32_t get32(uint8_t const* const p)
    {
        return static_cast<uint32_t>(p[0]) | (static_cast<uint32_t>(p[1]) << 8U) | (static_cast<uint32_t>(p[2]) << 16U)
               | (static_cast<uint32_t>(p[3]) << 24U);
    }

    static uint8_t saturatedIncrement(uint8_t const v) { return (v < 0xFFU) ? static_cast<uint8_t>(v + 1U) : v; }

    uint8_t* entryData(uint8_t const e) { return &_data[static_cast<size_t>(e) * _config.entryDataBytes]; }

    uint8_t const* entryData(uint8_t const e) const { return &_data[static_cast<size_t>(e) * _config.entryDataBytes]; }

    int32_t entryOfLocked(uint16_t const dtc) const
    {
        for (uint8_t e = 0U; e < _config.maxEntries; ++e)
        {
            if (_entries[e].dtc == static_cast<uint16_t>(dtc + 1U))
            {
                return static_cast<int32_t>(e);
            }
        }
        return -1;
    }

    int32_t copyStored(uint16_t const dtc, uint32_t const offset, uint32_t const bytes, uint8_t* const out, size_t const max) const
    {
        Lock const lock;
        int32_t const entry = entryOfLocked(dtc);
        if (entry < 0)
        {
            return 0;
        }
        size_t const n = (bytes < max) ? bytes : max;
        (void)std::memcpy(out, &entryData(static_cast<uint8_t>(entry))[offset], n);
        return static_cast<int32_t>(n);
    }

    static uint8_t counterValue(DtcState const& s, Counter const content)
    {
        switch (content)
        {
            case Counter::OCCURRENCE: return s.occurrence;
            case Counter::AGING: return s.aging;
            case Counter::FAULT_DETECTION: return static_cast<uint8_t>(s.fdc);
            case Counter::FAILED_CYCLES: return s.failedCycles;
            case Counter::CYCLES_SINCE_FIRST_FAILED: return s.cyclesSinceFirstFailed;
            default: return 0xFFU;
        }
    }

    static void resetDebounce(DtcState& s)
    {
        s.direction = 0;
        s.counter   = 0;
        s.elapsedMs = 0U;
        s.fdc       = 0;
    }

    void clearLocked(uint16_t const dtc)
    {
        DtcState& s               = _states[dtc];
        s.status                  = status::INITIAL;
        s.occurrence              = 0U;
        s.aging                   = 0U;
        s.failedCycles            = 0U;
        s.cyclesSinceFirstFailed  = 0U;
        resetDebounce(s);
        int32_t const entry = entryOfLocked(dtc);
        if (entry >= 0)
        {
            _entries[entry] = Entry{0U, 0U};
            (void)std::memset(entryData(static_cast<uint8_t>(entry)), 0, _config.entryDataBytes);
        }
        _eventsDirty  = true;
        _entriesDirty = true;
    }

    void clearAllLocked()
    {
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            clearLocked(i);
        }
        for (uint8_t e = 0U; e < _config.maxEntries; ++e)
        {
            _entries[e] = Entry{0U, 0U};
        }
        (void)std::memset(_data, 0, static_cast<size_t>(_config.maxEntries) * _config.entryDataBytes);
        _stamp = 0U;
    }

    Result takeLatchLocked(DtcState& s)
    {
        if (!s.latchValid)
        {
            return Result::NONE;
        }
        // the reported level stays (a BSW monitor reports on a change, the DEM samples every cycle); a failure
        // reported and passed again between two cycles is sampled failed once, then the level
        Result result = s.latchLast;
        if (s.latchFailed && (result != Result::FAILED) && (result != Result::PREFAILED))
        {
            result = Result::PREFAILED;
        }
        s.latchFailed = false;
        return result;
    }

    /** Debouncing: one sample into the fault detection counter; the matured result or NONE. */
    Result debounceLocked(DtcConfig const& dtc, DtcState& s, Result const sample)
    {
        if (dtc.debounce == DebounceKind::COUNTER)
        {
            CounterDebounce const& c = dtc.counter;
            int32_t counter          = s.counter;
            Result matured           = Result::NONE;
            switch (sample)
            {
                case Result::FAILED: counter = c.failedThreshold; break;
                case Result::PASSED: counter = c.passedThreshold; break;
                case Result::PREFAILED:
                    if (counter < c.jumpUp)
                    {
                        counter = c.jumpUp;
                    }
                    counter += c.increment;
                    counter = (counter > c.failedThreshold) ? c.failedThreshold : counter;
                    break;
                case Result::PREPASSED:
                    if (counter > c.jumpDown)
                    {
                        counter = c.jumpDown;
                    }
                    counter -= c.decrement;
                    counter = (counter < c.passedThreshold) ? c.passedThreshold : counter;
                    break;
                default: return Result::NONE;
            }
            if (counter >= c.failedThreshold)
            {
                matured = Result::FAILED;
            }
            else if (counter <= c.passedThreshold)
            {
                matured = Result::PASSED;
            }
            s.counter = static_cast<int16_t>(counter);
            if (counter >= 0)
            {
                s.fdc = static_cast<int8_t>((counter * 127) / c.failedThreshold);
            }
            else
            {
                s.fdc = static_cast<int8_t>(-((-counter * 128) / -static_cast<int32_t>(c.passedThreshold)));
            }
            return matured;
        }
        TimeDebounce const& t = dtc.time;
        bool const failed     = (sample == Result::FAILED) || (sample == Result::PREFAILED);
        int8_t const dir      = failed ? int8_t{1} : int8_t{-1};
        uint32_t const limit  = failed ? t.failedMs : t.passedMs;
        if ((sample == Result::FAILED) || (sample == Result::PASSED))
        {
            s.direction = dir;
            s.elapsedMs = limit;
        }
        else if (s.direction != dir)
        {
            s.direction = dir; // a new direction starts at zero (D.6: the counter jumps over zero)
            s.elapsedMs = 0U;
        }
        else if (s.elapsedMs < limit)
        {
            s.elapsedMs += _config.cycleMs;
            s.elapsedMs = (s.elapsedMs > limit) ? limit : s.elapsedMs;
        }
        uint64_t const scaled = (limit == 0U) ? 128U : ((static_cast<uint64_t>(s.elapsedMs) * (failed ? 127U : 128U)) / limit);
        if (failed)
        {
            s.fdc = static_cast<int8_t>((scaled > 127U) ? 127U : scaled);
        }
        else
        {
            s.fdc = static_cast<int8_t>(-static_cast<int32_t>((scaled > 128U) ? 128U : scaled));
        }
        if (s.elapsedMs >= limit)
        {
            return failed ? Result::FAILED : Result::PASSED;
        }
        return Result::NONE;
    }

    /** One sample of DTC \p i; true if the DTC has to be stored now (confirmed without an entry). */
    bool processLocked(uint16_t const i, Result const sample)
    {
        DtcConfig const& dtc = _config.dtcs[i];
        DtcState& s          = _states[i];
        if ((sample == Result::NONE) || !_dtcSetting || ((_conditions & dtc.conditions) != dtc.conditions)
            || ((_running & bit8(dtc.cycle)) == 0U))
        {
            return false; // discarded: the debouncing stands (enable conditions, 85 off, no cycle running)
        }
        Result const matured = debounceLocked(dtc, s, sample);
        uint8_t const before = s.status;
        bool newFailure      = false; // first failure of the cycle or testFailed 0 -> 1: try to store
        if (matured == Result::FAILED)
        {
            bool const firstThisCycle = (s.status & status::TEST_FAILED_THIS_OPERATION_CYCLE) == 0U;
            newFailure                = firstThisCycle || ((s.status & status::TEST_FAILED) == 0U);
            if ((s.status & status::TEST_FAILED) == 0U)
            {
                s.occurrence = saturatedIncrement(s.occurrence);
                _eventsDirty = true;
            }
            s.status = clearBits8(setBits8(s.status, FAILED_SETS), FAILED_CLEARS);
            if (firstThisCycle)
            {
                s.failedCycles = saturatedIncrement(s.failedCycles);
                s.aging        = 0U;
                _eventsDirty   = true;
            }
        }
        else if (matured == Result::PASSED)
        {
            s.status = clearBits8(s.status, PASSED_CLEARS);
        }
        _eventsDirty = _eventsDirty || (before != s.status);
        // a failure that stays does not retry a full memory every cycle, only the next new failure does
        return newFailure && ((s.status & status::CONFIRMED_DTC) == 0U) && (s.failedCycles >= dtc.confirmationThreshold);
    }

    void startCycleLocked(uint8_t const cycle)
    {
        _running = static_cast<uint8_t>(_running | bit8(cycle));
        if (!_dtcSetting)
        {
            return;
        }
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            if (_config.dtcs[i].cycle != cycle)
            {
                continue;
            }
            DtcState& s = _states[i];
            s.status    = setBits8(
                clearBits8(s.status, status::TEST_FAILED_THIS_OPERATION_CYCLE),
                status::TEST_NOT_COMPLETED_THIS_OPERATION_CYCLE);
            s.direction = 0;
            s.counter   = 0;
            s.elapsedMs = 0U;
            s.fdc       = 0;
        }
        _eventsDirty = true;
    }

    void endCycleLocked(uint8_t const cycle)
    {
        _running = clearBits8(_running, bit8(cycle));
        if (!_dtcSetting)
        {
            return;
        }
        for (uint16_t i = 0U; i < _config.dtcCount; ++i)
        {
            DtcConfig const& dtc = _config.dtcs[i];
            DtcState& s          = _states[i];
            bool const tested    = (s.status & status::TEST_NOT_COMPLETED_THIS_OPERATION_CYCLE) == 0U;
            bool const failed    = (s.status & status::TEST_FAILED_THIS_OPERATION_CYCLE) != 0U;
            // aging first: it looks at the cycle that ends (D.7)
            if ((dtc.agingCycle == cycle) && (dtc.agingThreshold != 0U) && ((s.status & status::CONFIRMED_DTC) != 0U))
            {
                if (failed)
                {
                    s.aging = 0U;
                }
                else if (tested)
                {
                    s.aging = saturatedIncrement(s.aging);
                    if (s.aging >= dtc.agingThreshold)
                    {
                        s.status       = clearBits8(s.status, status::CONFIRMED_DTC);
                        s.failedCycles = 0U;
                        int32_t const entry = entryOfLocked(i);
                        if (entry >= 0)
                        {
                            _entries[entry] = Entry{0U, 0U};
                            _entriesDirty   = true;
                        }
                    }
                }
            }
            if (dtc.cycle != cycle)
            {
                continue;
            }
            if (tested && !failed)
            {
                s.status = clearBits8(s.status, status::PENDING_DTC);
                if ((s.status & status::CONFIRMED_DTC) == 0U)
                {
                    s.failedCycles = 0U; // confirmation counts cycles with failures while the DTC is pending
                }
            }
            if ((s.status & status::TEST_FAILED_SINCE_LAST_CLEAR) != 0U)
            {
                s.cyclesSinceFirstFailed = saturatedIncrement(s.cyclesSinceFirstFailed);
            }
        }
        _eventsDirty = true;
    }

    /** Reads the data identifiers of DTC \p i into the scratch buffer (without the lock), then stores the entry. */
    void storeEntry(uint16_t const i)
    {
        DtcConfig const& dtc = _config.dtcs[i];
        IDidReader* const reader = (_reader != nullptr) ? _reader : registry.didReader;
        uint16_t const bytes = storedBytes(dtc);
        uint32_t offset      = 0U;
        auto const capture   = [&](uint16_t const did, uint16_t const n)
        {
            if ((offset + n) > _config.entryDataBytes)
            {
                return;
            }
            if ((reader == nullptr) || !reader->read(did, &_scratch[offset], n))
            {
                (void)std::memset(&_scratch[offset], 0xFF, n);
            }
            offset += n;
        };
        for (uint8_t r = 0U; r < dtc.snapshotCount; ++r)
        {
            for (uint8_t k = 0U; k < dtc.snapshots[r].count; ++k)
            {
                capture(dtc.snapshots[r].items[k].did, dtc.snapshots[r].items[k].bytes);
            }
        }
        for (uint8_t r = 0U; r < dtc.extendedCount; ++r)
        {
            for (uint8_t k = 0U; k < dtc.extended[r].count; ++k)
            {
                if (dtc.extended[r].items[k].content == Counter::DID)
                {
                    capture(dtc.extended[r].items[k].did, dtc.extended[r].items[k].bytes);
                }
            }
        }
        Lock const lock;
        DtcState& s = _states[i];
        if (((s.status & status::CONFIRMED_DTC) != 0U) || (s.failedCycles < dtc.confirmationThreshold) || !_dtcSetting)
        {
            return; // changed meanwhile (cleared, confirmed by another path, 85 off)
        }
        int32_t entry = entryOfLocked(i);
        if (entry < 0)
        {
            entry = freeEntryLocked(dtc);
        }
        if (entry < 0)
        {
            ++_overflows; // memory full and nothing displaceable: the DTC is not confirmed (it stays pending)
            return;
        }
        _entries[entry] = Entry{static_cast<uint16_t>(i + 1U), _stamp};
        ++_stamp;
        (void)std::memset(entryData(static_cast<uint8_t>(entry)), 0, _config.entryDataBytes);
        (void)std::memcpy(entryData(static_cast<uint8_t>(entry)), _scratch, bytes);
        s.status      = static_cast<uint8_t>(s.status | status::CONFIRMED_DTC);
        s.aging       = 0U;
        _eventsDirty  = true;
        _entriesDirty = true;
    }

    /** A free entry, or with replaceOldest the least important (largest priority number), oldest entry that is not
     * more important than \p dtc; -1 if none. */
    int32_t freeEntryLocked(DtcConfig const& dtc)
    {
        int32_t victim = -1;
        for (uint8_t e = 0U; e < _config.maxEntries; ++e)
        {
            if (_entries[e].dtc == 0U)
            {
                return static_cast<int32_t>(e);
            }
        }
        if (!_config.replaceOldest)
        {
            return -1;
        }
        for (uint8_t e = 0U; e < _config.maxEntries; ++e)
        {
            DtcConfig const& other = _config.dtcs[_entries[e].dtc - 1U];
            if (other.priority < dtc.priority)
            {
                continue; // more important than the new one
            }
            if (victim < 0)
            {
                victim = static_cast<int32_t>(e);
                continue;
            }
            DtcConfig const& best = _config.dtcs[_entries[victim].dtc - 1U];
            if ((other.priority > best.priority)
                || ((other.priority == best.priority) && (_entries[e].stamp < _entries[victim].stamp)))
            {
                victim = static_cast<int32_t>(e);
            }
        }
        if (victim >= 0)
        {
            DtcState& old = _states[_entries[victim].dtc - 1U];
            old.status    = clearBits8(old.status, status::CONFIRMED_DTC); // no entry, not confirmed
            old.aging     = 0U;
            _entries[victim] = Entry{0U, 0U};
            ++_displaced;
        }
        return victim;
    }

    Config const& _config;
    DtcState* const _states;
    Entry* const _entries;
    uint8_t* const _data;
    uint8_t* const _scratch;
    IDidReader* _reader;
    uint32_t _stamp;
    uint32_t _overflows;
    uint32_t _displaced;
    uint32_t _conditions;
    uint8_t _running;
    bool _dtcSetting;
    bool _loaded;
    bool _eventsDirty;
    bool _entriesDirty;
};

} // namespace dem
